#!/bin/sh
# Print the three IP addresses that appear most often in access.log.
# Ties are broken by first appearance in the log.

awk '{
    if (!first[$1]) {
        first[$1] = NR
    }
    count[$1]++
}
END {
    for (ip in count) {
        print count[ip], first[ip], ip
    }
}' access.log |
sort -k1,1nr -k2,2n |
head -n 3 |
awk '{print $3}'
